import{_ as t,o as r,c as d,a2 as o}from"./chunks/framework.D7WGirly.js";const m=JSON.parse('{"title":"Node and browser compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"compatibility.md","filePath":"compatibility.md"}'),a={name:"compatibility.md"};function i(s,e,n,c,p,y){return r(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="node-and-browser-compatibility" tabindex="-1">Node and browser compatibility <a class="header-anchor" href="#node-and-browser-compatibility" aria-label="Permalink to &quot;Node and browser compatibility&quot;">​</a></h1><p>The package exposes the same Promise-based class and shared TypeScript interface in Node and browsers. Native ESM, CommonJS, browser bundlers, and the browser global build are covered by consumer smoke checks.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Node</th><th>Browser</th></tr></thead><tbody><tr><td>Generate RSA/SPKI + PKCS#8 keys</td><td>Nonblocking <code>crypto.generateKeyPair</code></td><td><code>crypto.subtle.generateKey</code></td></tr><tr><td>Direct RSA-OAEP encryption</td><td>SHA-1 default; SHA-256 opt-in</td><td>Same</td></tr><tr><td>AES-256-GCM hybrid encryption</td><td>Legacy default; v1 opt-in</td><td>Same</td></tr><tr><td>RSA-PSS signatures</td><td>SHA-256, 32-byte salt</td><td>Same</td></tr><tr><td>JSON encryption</td><td>Bounded v1 SHA-256 hybrid + schema parser</td><td>Same</td></tr><tr><td>Signed messages</td><td>Canonical claims, expiry, atomic replay callback</td><td>Same</td></tr><tr><td>Strict RSA key helpers</td><td>Async parsing; SPKI/PKCS#8</td><td>Same</td></tr><tr><td>PEM formatting helpers</td><td>Synchronous header/footer checks</td><td>Same</td></tr><tr><td>Buffer methods</td><td>Accept <code>Uint8Array</code>/<code>Buffer</code>; return <code>Buffer</code></td><td>Accept/return <code>Uint8Array</code></td></tr><tr><td>Legacy private-key <code>encrypt</code> / public-key <code>decrypt</code></td><td>Supported</td><td>Rejected Promise</td></tr><tr><td>Cryptographic operation keys</td><td>Also accepts legacy PKCS#1</td><td>SPKI/PKCS#8 only</td></tr><tr><td>Missing-key failure</td><td>Rejected Promise</td><td>Rejected Promise</td></tr><tr><td>Unicode including leading BOM</td><td>Preserved</td><td>Preserved</td></tr></tbody></table><p>Node 22 and 24 are the CI targets. Browser operations require a secure context and Web Crypto. Browser code has no Node crypto or Buffer dependency. Browser tests execute in Chromium; compatibility with every browser release is not implied.</p><p>Both sides may use keys generated on either side. Direct encryption requires an agreed OAEP hash; hybrid v1 payloads identify their hash. Signatures use the same fixed RSA-PSS parameters in both builds. Constructor keys are defaults for operations; key generation returns keys without changing the instance.</p><p>For Node CommonJS, use <code>require(&#39;encrypt-rsa&#39;).default</code>. For Node ESM and browser bundlers, use <code>import NodeRSA from &#39;encrypt-rsa&#39;</code>. The standalone browser script exposes <code>encryptRSA.NodeRSA</code> and convenience functions for key generation, direct/hybrid strings, signatures, and strict RSA validation.</p>',6)])])}const h=t(a,[["render",i]]);export{m as __pageData,h as default};
